column6:
x = 10
if x > 20:
    print("big")
elif x > 5:
    print("medium")  # ← this runs
else:
    print("small")

Conditions are evaluated top-to-bottom; first True branch wins. elif and else are optional.

for name in ["alice", "bob", "carol"]:
    print(name.upper())

Iterates over any iterable: lists, strings, dicts, files, generators, range().

for n in range(100):
    if n > 4:
        break
    print(n)  # prints 0 1 2 3 4

Exits the innermost loop immediately.

for n in range(5):
    if n == 2:
        continue
    print(n)  # prints 0 1 3 4

Skips the rest of the current iteration, jumps to the next one.

class NotYet:
    pass  # placeholder — class body can't be empty

def todo():
    pass  # same for functions

Does nothing. Used as a syntactic placeholder.

def countdown(n):
    while n > 0:
        yield n
        n -= 1

for x in countdown(3):
    print(x)  # 3 2 1

Pauses the function and produces a value. Resumes on next iteration. Memory-efficient for large sequences.

class Dog:
    def __init__(self, name):
        self.name = name
    def speak(self):
        return f"{self.name} says woof"

d = Dog("Rex")
print(d.speak())  # Rex says woof

class Counter:
    def __init__(self):
        self.count = 0
    def inc(self):
        self.count += 1

self is the instance — it's how methods access the object's data. Not a keyword, but always the first parameter.

try:
    x = int("not a number")
except ValueError as e:
    print(f"bad input: {e}")

Catch specific exceptions. Avoid bare except: — always name the exception type.

try:
    f = open("data.txt")
except FileNotFoundError:
    print("missing")
else:
    print(f.read())  # runs only if no exception
finally:
    print("always runs")  # cleanup goes here

def divide(a, b):
    if b == 0:
        raise ValueError("cannot divide by zero")
    return a / b

Raise an exception explicitly. raise without args re-raises the current exception in an except block.

def avg(nums):
    assert len(nums) > 0, "empty list"
    return sum(nums) / len(nums)

Raises AssertionError if condition is False. Disabled with python -O. Use for sanity checks, not input validation.

def find(lst, target):
    for item in lst:
        if item == target:
            return item
    return None  # explicit "not found"

result = find([1,2,3], 99)
if result is None:
    print("not found")

Python's null. There is exactly one None object. Always test with is None, not ==.

squares = {x: x**2 for x in range(5)}
# {0: 0, 1: 1, 2: 4, 3: 9, 4: 16}

inverse = {v: k for k, v in squares.items()}
# {0: 0, 1: 1, 4: 2, 9: 3, 16: 4}

names = ["alice", "bob"]
ages = [30, 25]

for name, age in zip(names, ages):
    print(f"{name} is {age}")

dict(zip(names, ages))  # {"alice": 30, "bob": 25}

Stops at the shortest iterable. Use itertools.zip_longest to pad.

def log_calls(fn):
    def wrapper(*args, **kwargs):
        print(f"calling {fn.__name__}")
        return fn(*args, **kwargs)
    return wrapper

@log_calls
def add(a, b):
    return a + b

add(1, 2)  # prints "calling add", returns 3

@decorator is syntactic sugar for: add = log_calls(add)

def f(*args, **kwargs):
    print(args)    # tuple of positional args
    print(kwargs)  # dict of keyword args

f(1, 2, x=3, y=4)
# (1, 2)
# {'x': 3, 'y': 4}

# Keyword-only args (after *):
def g(a, b, *, verbose=False):
    pass  # verbose must be passed by name

def greet(name: str, times: int = 1) -> str:
    return (f"hello {name}\n") * times

from typing import Optional
def find(lst: list[int], target: int) -> Optional[int]:
    return target if target in lst else None

Hints are not enforced at runtime. Use mypy for static checking. Python 3.9+ allows list[int] instead of List[int].

# Parentheses instead of brackets → lazy evaluation
total = sum(x**2 for x in range(1000000))  # no list in memory

lines = (line.strip() for line in open("big.log"))
for line in lines:
    if "ERROR" in line:
        print(line)

class Circle:
    def __init__(self, radius):
        self._radius = radius

    @property
    def area(self):
        return 3.14159 * self._radius ** 2

c = Circle(5)
print(c.area)  # 78.53975 — no parentheses

Makes a method look like an attribute. Add @area.setter for write access.

class Date:
    def __init__(self, y, m, d):
        self.y, self.m, self.d = y, m, d

    @classmethod
    def from_str(cls, s):
        return cls(*map(int, s.split("-")))

    @staticmethod
    def is_valid(s):
        return len(s.split("-")) == 3

Date.from_str("2026-04-11")  # creates Date
Date.is_valid("2026-04-11")  # True

class Point:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __repr__(self):
        return f"Point({self.x}, {self.y})"

p = Point(1, 2)
print(p)  # Point(1, 2)

__init__ sets up the instance. __repr__ controls how it prints.

class Deck:
    def __init__(self):
        self.cards = list(range(52))
    def __len__(self):
        return len(self.cards)
    def __getitem__(self, i):
        return self.cards[i]

d = Deck()
len(d)    # 52
d[0]      # 0
d[-1]     # 51
d[2:5]    # [2, 3, 4] — slicing works too

class Vec:
    def __init__(self, x, y):
        self.x, self.y = x, y
    def __add__(self, other):
        return Vec(self.x + other.x, self.y + other.y)
    def __eq__(self, other):
        return self.x == other.x and self.y == other.y

Vec(1,2) + Vec(3,4)   # Vec(4, 6)
Vec(1,2) == Vec(1,2)  # True

class Animal:
    def speak(self):
        return "..."

class Dog(Animal):
    def speak(self):
        return "woof"

class Cat(Animal):
    def speak(self):
        return "meow"

for a in [Dog(), Cat()]:
    print(a.speak())  # woof, meow

Subclasses override parent methods. Use super() to call the parent.

class Base:
    def __init__(self, x):
        self.x = x

class Child(Base):
    def __init__(self, x, y):
        super().__init__(x)
        self.y = y

c = Child(1, 2)
print(c.x, c.y)  # 1 2

Delegates to the next class in the MRO. Always use super() in __init__ for cooperative inheritance.

class ValidationError(Exception):
    def __init__(self, field, message):
        self.field = field
        super().__init__(f"{field}: {message}")

try:
    raise ValidationError("email", "invalid format")
except ValidationError as e:
    print(e)        # email: invalid format
    print(e.field)  # email

from collections import defaultdict

counts = defaultdict(int)
for word in "the cat sat on the mat".split():
    counts[word] += 1
# {'the': 2, 'cat': 1, 'sat': 1, 'on': 1, 'mat': 1}

groups = defaultdict(list)
for name, dept in [("alice","eng"), ("bob","eng"), ("carol","hr")]:
    groups[dept].append(name)
# {'eng': ['alice','bob'], 'hr': ['carol']}

from concurrent.futures import ProcessPoolExecutor

def crunch(n):
    return sum(i*i for i in range(n))

with ProcessPoolExecutor(max_workers=4) as pool:
    results = list(pool.map(crunch, [10**6]*4))

Bypasses the GIL — true parallelism for CPU-bound work. Each worker is a separate process.

from abc import ABC, abstractmethod

class Shape(ABC):
    @abstractmethod
    def area(self) -> float:
        ...

class Circle(Shape):
    def __init__(self, r):
        self.r = r
    def area(self):
        return 3.14 * self.r ** 2

# Shape()   → TypeError (can't instantiate)
Circle(5).area()  # 78.5

import hashlib

h = hashlib.sha256(b"hello world").hexdigest()
# "b94d27b9934d3e08a52e52d7da7dabfa..."

# Hash a file
def file_hash(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

for n in [2, 3, 5, 7]:
    if n == 4:
        print("found 4")
        break
else:
    print("4 not found")  # ← runs because no break

The else block runs only if the loop completes without break. Useful for search patterns.
